/**
 * Parameter types for each tool, mapped by tool name
 */
export type ToolParams = {
  [CATALOG_PLACE_BASKET]: CatalogPlaceBasketParams;
  [CATALOG_LIST_ITEMS]: CatalogListItemsParams;
  [CATALOG_GET_ITEM]: CatalogGetItemParams;
  [CATALOG_SHELVE_ITEM]: CatalogShelveItemParams;
  [CATALOG_LIST_KINDS]: CatalogListKindsParams;
};

/**
 * Invokes a tool by name using the SDK. A tool whose bindingStatus is
 * unsupported_multipart uploads a file, which tool parameters cannot carry;
 * invokeTool throws for it without sending a request.
 *
 * @param sdk - The initialized SDK instance
 * @param toolName - The namespaced tool name (e.g., "auth.sendMagicLink")
 * @param params - The parameters for the tool
 * @returns The result of the tool invocation
 * @throws Error if the tool name is not recognized
 *
 * @example
 * ```typescript
 * const sdk = new FixtureRefsApiSDK({ baseUrl: 'https://api.example.com' });
 * const result = await invokeTool(sdk, 'auth.sendMagicLink', { email: 'user@example.com' });
 * ```
 */
export async function invokeTool<T extends ToolName>(
  sdk: FixtureRefsApiSDK,
  toolName: T,
  params: ToolParams[T]
): Promise<unknown> {
  switch (toolName) {
    case CATALOG_PLACE_BASKET:
      return sdk.catalog.placeBasket({ lines: (params as CatalogPlaceBasketParams).lines, giftSku: (params as CatalogPlaceBasketParams).giftSku });
    case CATALOG_LIST_ITEMS:
      return sdk.catalog.listItems({ q: (params as CatalogListItemsParams).q, ids: (params as CatalogListItemsParams).ids, inStock: (params as CatalogListItemsParams).inStock });
    case CATALOG_GET_ITEM:
      return sdk.catalog.getItem((params as CatalogGetItemParams).itemId);
    case CATALOG_SHELVE_ITEM:
      return sdk.catalog.shelveItem((params as CatalogShelveItemParams).itemId, { kind: (params as CatalogShelveItemParams).kind });
    case CATALOG_LIST_KINDS:
      return sdk.catalog.listKinds();
    default:
      throw new Error(`Unknown tool: ${toolName}`);
  }
}

/**
 * Gets the tool definition for a given tool name
 */
export function getToolDefinition(toolName: ToolName): ToolDefinition {
  return toolDefinitions[toolName];
}

/**
 * Gets all tools that require authentication
 */
export function getAuthRequiredTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.requiresAuth);
}

/**
 * Gets all tools that don't require authentication
 */
export function getPublicTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => !t.requiresAuth);
}

/**
 * Gets all tools for a specific namespace
 */
export function getToolsForNamespace(namespace: string): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.namespace === namespace);
}

/**
 * Validates that params contain all required fields for a tool
 */
export function validateToolParams(toolName: ToolName, params: Record<string, unknown>): { valid: boolean; missing: string[] } {
  const tool = toolDefinitions[toolName];
  const required = tool.parameters.required || [];
  const missing = required.filter(field => !(field in params) || params[field] === undefined);
  return { valid: missing.length === 0, missing };
}
